import {useId,type ReactNode} from 'react';
import './navigation.css';
type Row={id:string;label:string;icon?:ReactNode;disabled?:boolean};
type Section={label:string;rows:Row[]};
export function NavigationSidebar({sections,selected,onNavigate,onHelp,onSettings}:{sections:readonly [Section,Section];selected:string;onNavigate:(id:string)=>void;onHelp:()=>void;onSettings:()=>void}){
 const prefix=useId();
 return <aside className="nav-sidebar"><nav aria-label="Main navigation">{sections.map((section,index)=><section key={section.label} aria-labelledby={prefix+index}><h2 id={prefix+index}>{section.label}</h2><ul>{section.rows.map(row=><li key={row.id}><button disabled={row.disabled} aria-current={selected===row.id?'page':undefined} onClick={()=>onNavigate(row.id)}><span className="nav-icon" aria-hidden="true">{row.icon}</span><span>{row.label}</span>{row.disabled&&<span className="nav-unavailable">Unavailable</span>}</button></li>)}</ul></section>)}</nav><section className="workspace-summary" aria-label="Workspace summary"><h2>Design workspace</h2><p>12 projects · Team plan</p></section><footer><button onClick={onHelp}>Help</button><button onClick={onSettings}>Settings</button></footer></aside>;
}
export const exampleSections:readonly [Section,Section]=[{label:'Workspace',rows:[{id:'home',label:'Overview',icon:'⌂'},{id:'projects',label:'Projects'}]},{label:'Organization',rows:[{id:'people',label:'People',icon:'♧'},{id:'billing',label:'Billing',disabled:true}]}];
